/* Home dashboard - generated 2026-09-19. Desktop: 5 columns. Phone: 2 columns (auto flow). */
body,#app{background:#0d1014!important}
#grid-wrapper{grid-auto-rows:118px!important;grid-template-rows:none!important;padding:6px 8px 24px!important}
.tile{background:#161b22!important;border:1px solid #242c37;border-radius:16px!important;box-shadow:none!important;color:#e8edf3!important;overflow:hidden}
.tile .tile-title{font:600 12px/1.2 -apple-system,"SF Pro Text","Segoe UI",sans-serif!important;letter-spacing:.02em;color:#9aa7b5!important;padding:10px 12px 0!important;text-align:left!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;visibility:hidden;position:relative}
.tile .tile-title:after{visibility:visible;position:absolute;left:12px;top:10px;right:12px;overflow:hidden;text-overflow:ellipsis}
.tile .tile-primary{font:600 26px/1.1 -apple-system,"SF Pro Display","Segoe UI",sans-serif!important;color:#f2f5f8!important}
.tile:not(.thermostat) .tile-secondary{display:none!important}
.tile .tile-edit,.tile .tile-menu{display:none!important}
.tile .material-icons,.tile i{color:#9aa7b5}
.tile.switch:has(.tile-primary.on),.tile.dimmer:has(.tile-primary.on),.tile.outlet:has(.tile-primary.on){background:#3a2f12!important;border-color:#ffc857!important}
.tile .tile-primary.on i{color:#ffc857!important}
.tile.window:has(.tile-primary.open),.tile.contact:has(.tile-primary.open){background:#3d1a1a!important;border-color:#ff6b6b!important}
.tile.water:has(.tile-primary.wet){background:#3d1a1a!important;border-color:#ff6b6b!important}
.tile.shades:has(.tile-primary.open){background:#2a2440!important;border-color:#c9b8ff!important}
.header{background:#0d1014!important;color:#9aa7b5!important}

#tile-1 .tile-title:after{content:"Heating"}
#tile-1{border-left:3px solid #5fd0e0!important}
