.tile:not(.thermostat) .tile-contents{display:flex!important;flex-direction:column;align-items:center;justify-content:center;height:calc(100% - 30px)!important;padding:0 8px 8px!important}
.tile:not(.thermostat) .tile-primary{display:flex;flex-direction:column;align-items:center;gap:2px}
.tile .tile-primary i,.tile .tile-primary .material-icons{font-size:30px!important;line-height:1!important}
.tile.attribute .tile-primary{font-size:20px!important;text-transform:capitalize}

/* thermostat tile */
.tile.thermostat{padding:6px 10px!important}
.tile.thermostat .self-start .p-1{font:600 44px/1.1 -apple-system,"SF Pro Display","Segoe UI",sans-serif!important;color:#f2f5f8;padding-top:14px!important}
.tile.thermostat .self-start .p-1 small{font-size:18px;color:#9aa7b5}
.tile.thermostat .self-start .p-1 span{display:block;font:500 13px/1.4 -apple-system,"Segoe UI",sans-serif;color:#9aa7b5;text-transform:capitalize}
.tile.thermostat .flex-grow{margin-top:0!important;overflow:visible!important}
.tile.thermostat .pt-1 .inline-block{font:600 24px/1.15 -apple-system,"Segoe UI",sans-serif!important;min-width:96px}
.tile.thermostat .pt-1 .inline-block small{font-size:13px;color:#9aa7b5}
.tile.thermostat .pt-1 i{font-size:40px!important;color:#5fd0e0!important;vertical-align:middle;cursor:pointer}
.tile.thermostat .my-1{display:none!important}
.tile.thermostat .absolute.bottom-0{visibility:hidden}
.tile.thermostat .absolute.bottom-0:after{visibility:visible;content:"Heating - master setpoint";position:absolute;left:12px;bottom:8px;font:600 12px/1.2 -apple-system,"Segoe UI",sans-serif;color:#9aa7b5;letter-spacing:.02em}
.tile.thermostat:has(.self-start.heating){background:#40200f!important;border-color:#ff8a5c!important}
/* dimmer + shade tiles: icon, slider and value must fit one row */
.tile.dimmer .tile-primary,.tile.shades .tile-primary{font-size:15px!important;gap:0!important;width:100%}
.tile.dimmer .tile-primary i,.tile.shades .tile-primary i{font-size:22px!important}
.tile.dimmer .tile-primary .dimmer,.tile.shades .tile-primary .dimmer{width:100%}
.tile .vue-slider{padding:7px 0!important;height:6px!important;margin:0 14px!important}
.tile .vue-slider-rail{background:#2a3340!important}
.tile .vue-slider-process{background:#ffc857!important}
.tile.shades .vue-slider-process{background:#c9b8ff!important}
.tile .vue-slider-dot{width:16px!important;height:16px!important}
.tile .vue-slider-dot-tooltip{display:none!important}
